import { expect, test, uniqueName } from "../../fixtures";

const TAG = "@VEN-02";

const examples: Array<{ field: "name" | "category" | "contact_email"; value: string }> = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
];

for (const { field, value } of examples) {
  test(`rejects invalid vendor ${field} with validation_error`, { tag: TAG }, async ({ apiAs }) => {
    // Arrange: a otherwise-valid payload, with only the outlined field overridden.
    const member = await apiAs("member");
    const payload: Record<string, unknown> = {
      name: uniqueName("Vendor VEN02"),
      category: "software",
      contact_email: "ops@example.test",
    };
    payload[field] = value;

    // Act
    const response = await member.post("/api/vendors", { data: payload });

    // Assert
    expect(response.status()).toBe(422);
    const body = await response.json();
    expect(body.error?.code).toBe("validation_error");
    expect(JSON.stringify(body)).toContain(field);
  });
}
